{"implementation": "def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if segments is None or budget is None:
        raise ValueError("Missing segments or budget")
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError("Segments must be a non-empty list")
    if not isinstance(budget, int) or budget < 0:
        raise ValueError("Budget must be a non-negative integer")
    min_sum = 0
    cap_sum = 0
    for i, seg in enumerate(segments):
        required = ('name', 'importance', 'minimum', 'capacity')
        if not all(k in seg for k in required):
            raise ValueError(f"Segment {i} missing required keys")
        if not isinstance(seg['name'], str):
            raise ValueError("Segment name must be string")
        for k in ('importance', 'minimum', 'capacity'):
            if not isinstance(seg[k], int):
                raise ValueError(f"Segment {i} {k} must be integer")
        if seg['minimum'] < 0 or seg['capacity'] < seg['minimum']:
            raise ValueError("Invalid minimum or capacity")
        min_sum += seg['minimum']
        cap_sum += seg['capacity']
    if budget < min_sum:
        raise ValueError("Budget below total minimum")
    if budget > cap_sum:
        raise ValueError("Budget exceeds total capacity")
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_i = -1
        best_num = 0
        best_den = 1
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            num = seg['importance']
            den = alloc[i] + 1
            if best_i == -1:
                best_i = i
                best_num = num
                best_den = den
            else:
                if num * best_den > best_num * den:
                    best_i = i
                    best_num = num
                    best_den = den
                elif num * best_den == best_num * den:
                    if i < best_i:
                        best_i = i
                        best_num = num
                        best_den = den
        if best_i == -1:
            break
        alloc[best_i] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {"allocations": alloc, "by_name": by_name, "total": total}"}
